    await sleep(10)
    state = newState
  }

  const removeItem = async (name: string) => {
    removeItemSpy(name)
    await sleep(10)
    state = null
  }

  const getItemSpy = vi.fn()
  const setItemSpy = vi.fn()
  const removeItemSpy = vi.fn()

  return {
    storage: { getItem, setItem, removeItem },
    getItemSpy,
    setItemSpy,
    removeItemSpy,
  }
}

